  choices = $EXPL$["Alternative tax, Credits, Insurance premiums, and Depreciation recapture","Alimony (pre-2019), Contributions to IRA, Interest on student loans, Deduction for 50% SE tax","Adjusted income, Capital losses, Itemized deductions, and Dividends received","Accounting fees, Charitable gifts, Investment expenses, and Professional dues"]$EXPL$::jsonb,
